//! moonshot-folio-text (L2): UAX#14 line breaking and a greedy line wrapper (task F4.3).
//!
//! [`line_breaks`] lists the break opportunities of a text per Unicode Standard Annex #14;
//! [`wrap`] packs per-character advance widths into lines using those opportunities. The
//! Line_Break property data is a checked-in constant table generated by `gen/make_tables.pl`
//! (see `gen/README.md`); there is no build script and no third-party code.

#![forbid(unsafe_code)]
#![allow(clippy::doc_markdown)] // rule ids such as LB4 and UAX#14 are not code

mod breaks;
mod class;
#[cfg(test)]
mod oracle_tests;
#[allow(clippy::enum_glob_use, clippy::doc_markdown)]
mod tables;
mod wrap;

pub use breaks::{line_breaks, Break, BreakKind};
pub use tables::UNICODE_VERSION;
pub use wrap::wrap;
